int main(void)
{
    // Creation de 10 processus
    for (int i = 0; i < 10; ++i)
    {

        // Creation d'un processus fils
        int pid = fork();

        // Si i est a 9, on change la priorité a 5
        //if (i == 9) { chpr(getpid(), 5); }

        // Si le pid est 0, on est dans le processus fils
        if (pid == 0)
        {
            printf(1, "from child %d: process started\n", getpid());

            for (int k = 0; k < 300; ++k)
            {
                for (int i = 0 ; i < SIZE - 1; i++)
                {
                    for (int j = 0 ; j < SIZE - i - 1; j++)
                    {
                        if (tab[j] > tab[j + 1])
                        {
                            int tmp = tab[j];

                            tab[j] = tab[j + 1];
                            tab[j + 1] = tmp;
                        }
                    }
                }
            }

            printf(1, "from child %d: process is done\n", getpid());
            exit();
        }
    }

    for (int i = 0; i < 10; ++i) { wait(); }
    printf(1, "parent is done\n");
    exit();
}